OUTSIDE = ['-0.011502604124156085736702996783571084095112795563571941198347252115508733277951057', '0.031566304564559044105257664909173721694601688140964840386010671679052926377243907', '0.029304331516929078934748776843009435415579650072187257193228145283404181009007635', '0.048714478042089452955997319491567899808396680795668112539253038575916758612900312', '0.051790769733201908343648689840445597632753725571140190640968302907546975700182541', '0.000046577394627912540042894491840564707885640181337220126550491061522654765004610056', '0.0083099342608087602416816148311668618719028234800008057489838106253555359508436595', '-0.0025898621604632939568365754648730823707784287411883513770056672928101121770886286', '-0.034642334888249968703359134704006530808617184412560399503399337498576866538784742', '0.023557789326067116134611792281570921857564246080397627451003307596454240268598184', '0.016471344414356385998303446075025036645704745547597234591542753114736582044214355', '-0.06459469607724002481612768010916253545320032802698215710012266036600262523245379', '0.0040284531520430920619487787355855210494275420660972687144010125960398420625410618', '-0.011338985780714801955539283609730224360740763172997439955367039833619030179474287']
