def outside_point():
    """The certified point's Condon-Shortley components {m: w_m}, unnormalized, at double precision."""
    x = [float(s) for s in OUTSIDE]
    p = [complex(x[a], x[7 + a]) for a in range(7)]
    return {3 - a: sqrt(factorial(3 + (3 - a)) * factorial(3 - (3 - a))) * p[a] for a in range(7)}
